/* A monospace face fits the pixel look. */
[data-slot="sidebar"], [data-chat-header], [data-workspace-area="conversation"], [data-slot="composer-host"], [data-thread-details-card], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="dialog-popup"], [data-slot="button"], [data-slot="input"], [data-slot="select-trigger"], [data-settings-page-scroll] { font-family: ui-monospace, Consolas, monospace !important; }
/* The sidebar edge reads as pressed metal. */
[data-slot="sidebar-inner"] { border-right: 2px solid #3a2222 !important; box-shadow: inset -2px 0 0 rgba(224, 184, 114, 0.14) !important; }
/* The header seam stays inside the bottom 10px, so the title keeps its spacing. */
[data-chat-header] { background-image: linear-gradient(90deg, #8c1c26 0 25%, #d47622 25% 40%, #fcc96a 40% 60%, #d47622 60% 75%, #8c1c26 75%), repeating-linear-gradient(90deg, #d47622 0 2px, transparent 2px 4px) !important; background-size: 100% 2px, 100% 2px !important; background-position: left bottom, left bottom 4px !important; background-repeat: no-repeat !important; border-bottom: 2px solid #3a2222; }
/* The details card and the popups take square corners. */
[data-thread-details-card], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="dialog-popup"] { border: 2px solid #3a2222 !important; border-radius: 0 !important; box-shadow: inset 0 2px 0 rgba(242, 217, 166, 0.12), 0 2px 0 #0a0505 !important; }
[data-slot="button"], [data-slot="input"], [data-slot="select-trigger"] { border-radius: 0 !important; }
/* The composer is a plate made of small background blocks. Nothing is clipped. */
[data-slot="composer-host"] { --fr: #9a7a42; --fl: #1b0f0f; background-color: transparent !important; background-image: linear-gradient(var(--fr), var(--fr)), linear-gradient(var(--fr), var(--fr)), linear-gradient(var(--fr), var(--fr)), linear-gradient(var(--fr), var(--fr)), linear-gradient(var(--fr), var(--fr)), linear-gradient(var(--fr), var(--fr)), linear-gradient(var(--fr), var(--fr)), linear-gradient(var(--fr), var(--fr)), linear-gradient(var(--fl), var(--fl)), linear-gradient(var(--fl), var(--fl)) !important; background-size: calc(100% - 8px) 2px, calc(100% - 8px) 2px, 2px calc(100% - 8px), 2px calc(100% - 8px), 2px 2px, 2px 2px, 2px 2px, 2px 2px, calc(100% - 8px) calc(100% - 4px), calc(100% - 4px) calc(100% - 8px) !important; background-position: 4px 0, left 4px bottom 0, 0 4px, right 0 top 4px, 2px 2px, right 2px top 2px, left 2px bottom 2px, right 2px bottom 2px, 4px 2px, 2px 4px !important; background-repeat: no-repeat !important; border: 0 !important; border-radius: 0 !important; box-shadow: none !important; }
/* The app paints the composer fill on this pseudo-element, so the plate goes here too. */
[data-slot="composer-host"]::before { background-color: transparent !important; background-image: var(--pi) !important; background-size: var(--ps) !important; background-position: var(--pp) !important; background-repeat: no-repeat !important; border: 0 !important; border-radius: 0 !important; }
[data-slot="composer-host"]::after { border-radius: 0 !important; box-shadow: none !important; }
/* Gold marks focus. */
[data-slot="composer-host"]:focus-within { --fr: #e0b872; --rg: rgba(224, 184, 114, 0.4); }
.composer-tiptap { caret-color: #e0b872; }
.composer-tiptap ::selection { background: rgba(224, 184, 114, 0.32); }
/* The bubble fill sits on two pseudo-elements with stepped clip paths. The text stays unclipped. */
[data-user-message-bubble] { position: relative !important; isolation: isolate; background-color: transparent !important; background-image: none !important; border: 0 !important; border-radius: 0 !important; box-shadow: none !important; }
[data-user-message-bubble]::before { content: ""; position: absolute; inset: 0; z-index: -1; background: #6a4220; clip-path: polygon(0 4px, 4px 4px, 4px 0, calc(100% - 4px) 0, calc(100% - 4px) 4px, 100% 4px, 100% calc(100% - 4px), calc(100% - 4px) calc(100% - 4px), calc(100% - 4px) 100%, 4px 100%, 4px calc(100% - 4px), 0 calc(100% - 4px)); }
[data-user-message-bubble]::after { content: ""; position: absolute; inset: 2px; z-index: -1; background: #2c1a14; clip-path: polygon(0 2px, 2px 2px, 2px 0, calc(100% - 2px) 0, calc(100% - 2px) 2px, 100% 2px, 100% calc(100% - 2px), calc(100% - 2px) calc(100% - 2px), calc(100% - 2px) 100%, 2px 100%, 2px calc(100% - 2px), 0 calc(100% - 2px)); }
/* The code block has square corners and a gold stud in each corner. */
.chat-markdown-codeblock { border: 2px solid #3a2222 !important; border-radius: 0 !important; box-shadow: inset 0 2px 0 rgba(0, 0, 0, 0.5) !important; background-image: linear-gradient(#9a7a42, #9a7a42), linear-gradient(#9a7a42, #9a7a42), linear-gradient(#9a7a42, #9a7a42), linear-gradient(#9a7a42, #9a7a42) !important; background-size: 4px 4px !important; background-position: left 4px top 4px, right 4px top 4px, left 4px bottom 4px, right 4px bottom 4px !important; background-repeat: no-repeat !important; }
.chat-markdown-codeblock:hover { border-color: #6a4220 !important; }
/* Each thread row has a square ember. A working thread gets a hotter ember. */
[data-thread-item] { border-radius: 0 !important; padding-left: 18px !important; background-image: linear-gradient(#d47622, #d47622) !important; background-size: 4px 4px !important; background-position: 7px center !important; background-repeat: no-repeat !important; }
[data-thread-item]:has([aria-label*=", Working"]) { background-color: rgba(212, 118, 34, 0.16) !important; background-image: linear-gradient(#fff4d6, #fff4d6), linear-gradient(#fcc96a, #fcc96a), linear-gradient(rgba(212, 118, 34, 0.5), rgba(212, 118, 34, 0.5)) !important; background-size: 2px 2px, 6px 6px, 10px 10px !important; background-position: 7px center, 5px center, 3px center !important; }
[data-slot="project-monogram"] { border-radius: 0 !important; }
::-webkit-scrollbar-thumb { background: #4a2c1c; border-radius: 0; }
::-webkit-scrollbar-thumb:hover { background: #9a8372; }
[data-slot="scroll-area-thumb"] { background: #4a2c1c !important; border-radius: 0 !important; }
/* Headings take a gold rule. Links take gold. Inline code takes a steel tone. */
.chat-markdown h1, .chat-markdown h2, .chat-markdown h3 { color: #f7e3c4; border-bottom: 2px solid rgba(224, 184, 114, 0.4); padding-bottom: 0.2em; }
.chat-markdown a { color: #e0b872; text-decoration-color: rgba(224, 184, 114, 0.55); }
.chat-markdown :not(pre) > code { color: #b4c7da; }
/* The usage card shows the percent that remains, so the value says so. */
[data-thread-details-card] [aria-label$="% left"] > span:last-child::after { content: " left"; font-weight: 400; color: #b8a798; }
/* A thicker bar on a quiet track makes the level easy to read. */
[data-thread-details-card] [aria-label$="% left"] > span:nth-child(2), [data-thread-details-card] [aria-label^="Context:"] > span:nth-child(2) { height: 5px; background: #2b1818 !important; }
/* The limit bar takes the look gradient. The warning and error colours of the app stay. */
[data-thread-details-card] [aria-label$="% left"] > span:nth-child(2) > span:first-child:not([class*="bg-warning"]):not([class*="bg-error"]) { background: linear-gradient(90deg, #b3202e, #d47622, #e0b872) !important; }
[data-thread-details-card] [aria-label^="Context:"] > span:nth-child(2) > span:first-child:not([class*="bg-warning"]):not([class*="bg-error"]) { background: linear-gradient(90deg, #d47622, #fcc96a) !important; }
